import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Teacher Dashboard -> Messages / Chat (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/messages-chat.md","filePath":"modules/teacher-dashboard/messages-chat.md"}'),d={name:"modules/teacher-dashboard/messages-chat.md"};function r(n,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="teacher-dashboard-messages-chat-deep" tabindex="-1">Teacher Dashboard -&gt; Messages / Chat (deep) <a class="header-anchor" href="#teacher-dashboard-messages-chat-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Messages / Chat (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>messages-chat</code><br><strong>Route:</strong> <code>/teacher-dashboard/chat</code></p><p>This module provides instructor-to-student chat with a conversation list, message window, Redux chat state, Apollo GraphQL messaging, and Socket.IO events.</p><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/chat/index.tsx</code></td><td>Chat route page</td><td>Connects Redux chat state to <code>ChatList</code> and <code>ChatWindow</code>; selects default conversation and clears unread state.</td></tr><tr><td><code>Frontend/src/layouts/TeacherLayout.tsx</code></td><td>Conversation seeding and socket setup</td><td>Builds teacher conversations from <code>GET_ALL_STUDENTS</code>; joins socket rooms and dispatches received messages.</td></tr><tr><td><code>Frontend/src/components/Chat/ChatList.tsx</code></td><td>Conversation list UI</td><td>Shows available chat threads.</td></tr><tr><td><code>Frontend/src/components/Chat/ChatWindow.tsx</code></td><td>Message thread UI</td><td>Uses GraphQL and socket integration for messages.</td></tr><tr><td><code>Frontend/src/store/slices/chatSlice.ts</code></td><td>Chat Redux slice</td><td>Stores conversations, selected conversation, unread state, and messages.</td></tr><tr><td><code>Frontend/src/graphql/Queries/Chat.ts</code></td><td>Chat GraphQL</td><td>Defines <code>GET_MESSAGES</code>, <code>SEND_MESSAGE</code>, <code>NEW_MESSAGE_SUBSCRIPTION</code>.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="chat-thread-operations" tabindex="-1">Chat thread operations <a class="header-anchor" href="#chat-thread-operations" aria-label="Permalink to &quot;Chat thread operations&quot;">​</a></h3><ul><li><code>GET_MESSAGES(user1Id: ID!, user2Id: ID!)</code></li><li><code>SEND_MESSAGE(...)</code></li><li><code>NEW_MESSAGE_SUBSCRIPTION</code></li></ul><p>These are consumed primarily by <code>ChatWindow.tsx</code>.</p><h3 id="conversation-source" tabindex="-1">Conversation source <a class="header-anchor" href="#conversation-source" aria-label="Permalink to &quot;Conversation source&quot;">​</a></h3><ul><li><code>GET_ALL_STUDENTS</code><ul><li>Used by <code>TeacherLayout.tsx</code></li><li>Filters to students with lesson history and synthesizes conversation objects</li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/chat.typeDefs.js</code></li><li>Relevant fields: <ul><li><code>getMessages</code></li><li><code>sendMessage</code></li><li><code>messageSent</code> subscription</li></ul></li><li>Also declared but not clearly wired in current app: <ul><li><code>getConversations</code></li><li><code>createConversation</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/chat.resolvers.js</code></li><li>Relevant resolvers: <ul><li><code>Query.getMessages</code></li><li><code>Mutation.sendMessage</code></li><li><code>Subscription.messageSent</code></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/Message.js</code></td><td>Message persistence</td></tr><tr><td><code>server/src/models/Conversation.js</code></td><td>Conversation storage</td></tr><tr><td><code>server/src/socket/index.js</code></td><td>Room joins, typing events, and real-time socket delivery</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Teacher layout loads students with bookings and converts them into chat conversations in Redux.</li><li>Chat page selects a default conversation if one is not already selected.</li><li><code>ChatWindow</code> loads message history via <code>GET_MESSAGES</code>.</li><li>New messages are sent through <code>SEND_MESSAGE</code>.</li><li>Realtime updates arrive through Apollo subscription and socket events.</li><li>Redux state updates conversation/message lists and unread indicators.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>Conversation list is not loaded from dedicated GraphQL conversation queries; it is built in <code>TeacherLayout.tsx</code> from students with lesson history.</li><li>The schema declares some conversation operations that do not appear to be actively used by the current teacher chat UI.</li></ul>',22)])])}const b=t(d,[["render",r]]);export{p as __pageData,b as default};
